INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('ENEP/INEP', 'Matematica', 'No período de 2005 a 2013, o valor de venda dos imóveis em uma cidade apresentou alta, o que resultou no aumento dos aluguéis. Os gráficos apresentam a evolução desses valores, para um mesmo imóvel, no  
