INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('ENEP/INEP', 'Matematica', 'Uma pessoa precisa contratar um operário para fazer um serviço em sua casa. Para isso, ela postou um anúncio em uma rede social.  
