INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('ENEP/INEP', 'Matematica', 'Uma cozinheira produz docinhos especiais por encomenda. Usando uma receita-base de massa, ela prepara uma porção, com a qual produz 50 docinhos maciços de formato esférico, com 2 cm de diâmetro. Um cliente encomenda 150 desses docinhos, mas pede que cada um tenha formato esférico com 4 cm de diâmetro.  
