INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('ENEP/INEP', 'Matematica', 'A esperança de vida ao nascer é o número médio de anos que um indivíduo tende a viver a partir de seu nascimento, considerando dados da população. No Brasil, esse número vem aumentando consideravelmente, como mostra o gráfico.

